@Component public class PublicFeedFetcher {
 public record Item(String title,String summary,String url,String publishedAt){}
 public record Feed(String title,List<Item> items){}
 static final int MAX_BYTES=2*1024*1024;
 public static URI url(String raw){try{URI uri=URI.create(raw.trim());if(uri.toString().length()>2048||!"https".equalsIgnoreCase(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||uri.getFragment()!=null||(uri.getPort()!=-1&&uri.getPort()!=443))throw new IllegalArgumentException();String host=uri.getHost().toLowerCase(Locale.ROOT);if(host.matches("[0-9.]+")||host.contains(":")||!host.contains(".")||host.endsWith(".local")||host.endsWith(".internal")||host.endsWith(".localhost")||host.endsWith(".test")||host.equals("metadata.google.internal"))throw new IllegalArgumentException();return uri;}catch(Exception e){throw new IllegalArgumentException("Use a public HTTPS RSS/Atom feed URL on port 443");}}
 public static boolean publicAddress(InetAddress address){byte[] b=address.getAddress();if(address.isAnyLocalAddress()||address.isLoopbackAddress()||address.isLinkLocalAddress()||address.isSiteLocalAddress()||address.isMulticastAddress())return false;if(b.length==4){int a=b[0]&255,c=b[1]&255,d=b[2]&255;return a!=0&&a!=10&&a!=127&&a<224&&!(a==100&&c>=64&&c<=127)&&!(a==169&&c==254)&&!(a==172&&c>=16&&c<=31)&&!(a==192&&(c==168||c==0&&(d==0||d==2)||c==88&&d==99))&&!(a==198&&(c==18||c==19||c==51&&d==100))&&!(a==203&&c==0&&d==113);}return (b[0]&0xf0)==0x20&&!(b[0]==0x20&&b[1]==0x02)&&!(b[0]==0x20&&b[1]==0x01&&(b[2]==0||b[2]==0x0d&&b[3]==(byte)0xb8));}
 static DnsResolver resolver(){return new DnsResolver(){public InetAddress[] resolve(String host)throws UnknownHostException{InetAddress[] addresses=InetAddress.getAllByName(host);if(addresses.length==0||Arrays.stream(addresses).anyMatch(a->!publicAddress(a)))throw new UnknownHostException("Feed address is not public");return addresses;}public String resolveCanonicalHostname(String host){return host;}};}
 public Feed fetch(String raw)throws Exception{URI uri=url(raw);var manager=PoolingHttpClientConnectionManagerBuilder.create().setDnsResolver(resolver()).setDefaultConnectionConfig(ConnectionConfig.custom().setConnectTimeout(Timeout.ofSeconds(5)).setSocketTimeout(Timeout.ofSeconds(5)).build()).build();try(var client=HttpClients.custom().setConnectionManager(manager).disableRedirectHandling().disableAutomaticRetries().disableCookieManagement().setDefaultRequestConfig(RequestConfig.custom().setResponseTimeout(Timeout.ofSeconds(8)).build()).setUserAgent("MyAaptha-PublicFeed/1.0").build()){var request=new HttpGet(uri);request.setHeader("Accept","application/atom+xml, application/rss+xml, application/xml, text/xml");return client.execute(request,response->{if(response.getCode()!=200||response.getEntity()==null){request.cancel();throw new IOException("Feed unavailable; use its final public feed address");}if(response.getEntity().getContentLength()>MAX_BYTES){request.cancel();throw new IOException("Feed exceeds 2 MB");}try(var input=response.getEntity().getContent();var bytes=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];long deadline=System.nanoTime()+15_000_000_000L;int read;while((read=input.read(buffer))!=-1){if(bytes.size()+read>MAX_BYTES||System.nanoTime()>deadline){request.cancel();throw new IOException("Feed exceeds the size or time limit");}bytes.write(buffer,0,read);}try{return parse(bytes.toByteArray(),uri);}catch(Exception e){throw new IOException("Choose a valid RSS or Atom feed");}}});}}
 public Feed parse(byte[] bytes,URI base)throws Exception{if(bytes.length>MAX_BYTES)throw new IllegalArgumentException("Feed exceeds 2 MB");var factory=DocumentBuilderFactory.newInstance();factory.setNamespaceAware(true);factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);factory.setFeature("http://xml.org/sax/features/external-general-entities",false);factory.setFeature("http://xml.org/sax/features/external-parameter-entities",false);factory.setXIncludeAware(false);factory.setExpandEntityReferences(false);factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD,"");factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA,"");var builder=factory.newDocumentBuilder();builder.setErrorHandler(new org.xml.sax.helpers.DefaultHandler(){public void fatalError(org.xml.sax.SAXParseException e)throws org.xml.sax.SAXException{throw e;}});Element root=builder.parse(new ByteArrayInputStream(bytes)).getDocumentElement();boolean atom="feed".equals(root.getLocalName());if(!atom&&!"rss".equals(root.getLocalName())&&!"RDF".equals(root.getLocalName()))throw new IllegalArgumentException("Not a feed");Element channel=first(root,"channel");String title=text(atom?root:channel==null?root:channel,"title",300);NodeList nodes=root.getElementsByTagNameNS("*",atom?"entry":"item");List<Item> items=new ArrayList<>();Set<String> seen=new HashSet<>();for(int i=0;i<nodes.getLength()&&items.size()<50;i++){Element node=(Element)nodes.item(i);String link="";if(atom){for(Node child=node.getFirstChild();child!=null;child=child.getNextSibling())if(child instanceof Element e&&"link".equals(e.getLocalName())&&(e.getAttribute("rel").isEmpty()||"alternate".equals(e.getAttribute("rel")))){link=e.getAttribute("href");break;}}else link=text(node,"link",2048);try{link=url(base.resolve(link).toString()).toString();}catch(Exception e){continue;}if(!seen.add(link))continue;String itemTitle=text(node,"title",500);if(itemTitle.isBlank())itemTitle="Untitled post";String summary=text(node,atom?"summary":"description",1500);if(summary.isBlank()&&atom)summary=text(node,"content",1500);String date=text(node,atom?"published":"pubDate",100);if(date.isBlank()&&atom)date=text(node,"updated",100);items.add(new Item(itemTitle,summary,link,date(date)));}return new Feed(title.isBlank()?base.getHost():title,List.copyOf(items));}
 private static Element first(Element parent,String name){if(parent==null)return null;for(Node child=parent.getFirstChild();child!=null;child=child.getNextSibling())if(child instanceof Element e&&name.equals(e.getLocalName()))return e;return null;}
 private static String text(Element parent,String name,int length){Element child=first(parent,name);if(child==null)return "";String text=child.getTextContent().replaceAll("(?is)<[^>]*>"," ").replaceAll("\\s+"," ").trim();return text.substring(0,Math.min(length,text.length()));}
 private static String date(String raw){try{return Instant.parse(raw).toString();}catch(Exception ignored){try{return ZonedDateTime.parse(raw,DateTimeFormatter.RFC_1123_DATE_TIME).toInstant().toString();}catch(Exception none){return null;}}}
}
